'use strict';
const S=window.SITE;
let lang=localStorage.getItem('meleh-language')||'hr';
if(!['hr','en','de'].includes(lang))lang='hr';
const t=(hr,en,de)=>({hr,en,de}[lang]||hr);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'/',apartments:'/apartmani/',about:'/o-nama/',gallery:'/galerija/',contact:'/kontakt/',privacy:'/privatnost/',terms:'/uvjeti/'};
const url=(key)=>paths[key]||'/apartmani/'+key+'/';
const label=key=>({home:t('Naslovnica','Home','Startseite'),apartments:t('Apartmani','Apartments','Apartments'),about:t('O nama','Our story','Über uns'),gallery:t('Galerija','Gallery','Galerie'),contact:t('Kontakt','Contact','Kontakt')}[key]||key);
const cta=()=>t('Pošalji upit','Make an enquiry','Anfrage senden');
const pending=()=>t('Podatak uskoro','Details coming soon','Angaben folgen');
const image=key=>S.photos.find(p=>p.key===key)||S.photos[0];
const photo=(key,cls='',eager=false)=>{const p=image(key);return `<img class="${cls}" src="/assets/${p.file}" alt="${esc(t(p.alt,p.altEn||'Illustrative apartment interior',p.altDe||'Beispielinterieur eines Apartments'))}" ${eager?'fetchpriority="high"':'loading="lazy"'} width="1200" height="800">`};
function icon(name){const shapes={sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',sea:'<path d="M2 11c3-5 4 5 8 0s5 5 8 0 4 0 4 0M2 17c3-5 4 5 8 0s5 5 8 0 4 0 4 0M6 4h12"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',shop:'<path d="M4 10v11h16V10M3 4h18l1 6H2l1-6ZM9 21v-7h6v7M7 4l-1 6m6-6v6m5-6 1 6"/>',food:'<path d="M5 2v7c0 3 4 3 4 0V2M7 2v20M18 2c-4 5-4 10 0 10V2Zm0 10v10"/>',plane:'<path d="m22 2-7 20-4-9L2 9 22 2Zm-11 11L22 2"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-17a3 3 0 0 1 0 6m2 5a5 5 0 0 1 3 5"/>',bed:'<path d="M3 18V6m18 12V9M3 14h18M7 14V9h8a6 6 0 0 1 6 5M3 9h4m-4 9v3m18-3v3"/>',area:'<rect x="3" y="3" width="18" height="18" rx="1"/><path d="m7 17 10-10M7 11v6h6m-2-10h6v6"/>',leaf:'<path d="M20 3C8 1 1 9 6 16s16 3 14-13ZM5 21 17 8"/>',heart:'<path d="M20 5c-4-4-8 1-8 1S8 1 4 5c-5 5 8 15 8 15s13-10 8-15Z"/>',key:'<circle cx="8" cy="8" r="5"/><path d="m12 12 9 9m-3-3 3-3m-6 0 3-3"/>',chat:'<path d="M21 11a9 9 0 0 1-9 9 10 10 0 0 1-4-1l-6 3 2-6a9 9 0 1 1 17-5Z"/>',quote:'<path d="M10 5H4v7h6v6H4m16-13h-6v7h6v6h-6"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[name]||shapes.sun}</svg>`}
function brand(){return `<a class="brand" href="/" aria-label="Meleh Apartmani"><svg viewBox="0 0 40 40" fill="none" aria-hidden="true"><path d="M5 30V10l15 16 15-16v20M2 35c6-4 10 4 17 0s12 4 19 0" stroke="currentColor" stroke-width="1.5"/></svg><span class="brand-name">MELEH<span class="brand-sub">APARTMANI</span></span></a>`}
function header(){return `<div class="demo-bar">${t('OGLEDNA VERZIJA · Prizori Crikvenice su stvarni; interijeri i podaci apartmana su ogledni.','DEMO VERSION · Crikvenica photographs are real; apartment interiors and details are illustrative.','DEMO-VERSION · Echte Fotos von Crikvenica; Apartmentinterieurs und Angaben sind Beispiele.')}</div><header class="header"><div class="wrap nav">${brand()}<nav class="nav-links" aria-label="${t('Glavna navigacija','Main navigation','Hauptnavigation')}"><a href="/">${label('home')}</a><details class="dropdown"><summary>${label('apartments')}</summary><div class="dropdown-menu"><a href="/apartmani/">${t('Svi apartmani','All apartments','Alle Apartments')}</a>${S.apartments.map(a=>`<a href="${url(a.slug)}">${esc(a.name)}</a>`).join('')}</div></details>${['about','gallery','contact'].map(k=>`<a href="${url(k)}">${label(k)}</a>`).join('')}</nav><div class="nav-right"><button class="theme-toggle" type="button" aria-pressed="false"></button><select class="language" aria-label="${t('Jezik','Language','Sprache')}">${['hr','en','de'].map(l=>`<option value="${l}" ${lang===l?'selected':''}>${l.toUpperCase()}</option>`).join('')}</select><a class="btn" href="/kontakt/">${cta()} <span>↗</span></a><button class="menu-button" aria-expanded="false" aria-label="${t('Otvori izbornik','Open menu','Menü öffnen')}">☰</button></div></div></header>`}
function footer(){return `<section class="cta-band"><div class="wrap cta-inner"><div><h2>${t('Vaš odmor počinje jednom porukom.','Your holiday begins with a message.','Ihr Urlaub beginnt mit einer Nachricht.')}</h2><p>${t('Recite nam kada biste došli. Zajedno ćemo pronaći vaš kutak za odmor.','Tell us when you would like to visit. Let’s find your place to unwind.','Sagen Sie uns, wann Sie kommen möchten. Finden wir Ihren Ort zum Entspannen.')}</p></div><a class="btn light" href="/kontakt/">${cta()} <span>↗</span></a></div></section><footer class="footer"><div class="wrap"><div class="footer-grid"><div>${brand()}<p>${t('Prostor za opuštanje. Vrijeme za vaše najdraže. Otkrijte kako bi mogao izgledati vaš sljedeći odmor u apartmanima Meleh.','Space to unwind. Time for the people you love. Discover your next holiday at Meleh Apartments.','Raum zum Entspannen. Zeit für Ihre Liebsten. Entdecken Sie Ihren nächsten Urlaub in den Meleh Apartments.')}</p></div><div><h3>${label('apartments')}</h3><div class="footer-links">${S.apartments.map(a=>`<a href="${url(a.slug)}">${t('Apartman','Apartment','Apartment')} ${a.name}</a>`).join('')}</div></div><div><h3>${t('Istražite','Explore','Entdecken')}</h3><div class="footer-links">${['about','gallery','contact'].map(k=>`<a href="${url(k)}">${label(k)}</a>`).join('')}${S.instagram?`<a href="${esc(S.instagram)}">Instagram ↗</a>`:''}${S.facebook?`<a href="${esc(S.facebook)}">Facebook ↗</a>`:''}</div></div><div><h3>${label('contact')}</h3><div class="footer-links">${S.address?esc(S.address):t('Adresa će biti dodana','Address to be added','Adresse folgt')}${S.email?`<a href="mailto:${esc(S.email)}">${esc(S.email)}</a>`:`<span>${t('E-mail uskoro','Email coming soon','E-Mail folgt')}</span>`}${S.phone?`<a href="tel:${esc(S.phone)}">${esc(S.phone)}</a>`:`<span>${t('Telefon uskoro','Phone coming soon','Telefon folgt')}</span>`}</div></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Meleh Apartmani · ${t('Odmor u svom ritmu.','A stay at your own pace.','Urlaub in Ihrem Rhythmus.')}</span><div><a href="/privatnost/">${t('Privatnost','Privacy','Datenschutz')}</a><a href="/fotografije/">${t('Izvori fotografija','Photo credits','Bildnachweise')}</a><a href="/uvjeti/">${t('Uvjeti korištenja','Terms of use','Nutzungsbedingungen')}</a></div></div></div></footer><div class="mobile-cta"><span>${t('Vaš kutak za odmor','Your place to unwind','Ihr Ort zum Entspannen')}</span><a class="btn" href="/kontakt/">${cta()} ↗</a></div>`}
function specs(a){return `<div class="specs"><span>${icon('people')}${a.guests} ${t('osobe','guests','Personen')}</span><span>${icon('bed')}${a.rooms} ${t(a.rooms===1?'soba':'sobe',a.rooms===1?'bedroom':'bedrooms',a.rooms===1?'Schlafzimmer':'Schlafzimmer')}</span><span>${icon('area')}${a.area} m²</span></div>`}
function description(a){return a.type==='family'?t('Ogledni obiteljski apartman s prostorom za druženje i odmor. Primjer rasporeda s dvije spavaće sobe za zajedničke trenutke.','An illustrative family apartment with space to gather and relax. A two-bedroom layout for time together.','Ein beispielhaftes Familienapartment mit Platz zum Zusammensein. Zwei Schlafzimmer für gemeinsame Urlaubstage.'):t('Ogledni apartman u svijetlim, prirodnim tonovima. Zamišljen za mirna jutra i opuštene večeri udvoje.','An illustrative apartment in light, natural tones. Imagined for peaceful mornings and relaxed evenings together.','Ein beispielhaftes Apartment in hellen Naturtönen. Für ruhige Morgen und entspannte Abende zu zweit.')}
function cards(){return `<div class="apartments-grid">${S.apartments.map((a,i)=>`<article class="apartment-card"><a class="image-wrap" href="${url(a.slug)}">${photo(a.image)}<span class="image-label">${t('APARTMAN','APARTMENT','APARTMENT')} 0${i+1}</span></a><div class="card-body"><div class="card-title"><h3><a href="${url(a.slug)}">${a.name}</a></h3><span>${t('OGLEDNI PRIMJER','ILLUSTRATIVE','BEISPIEL')}</span></div>${specs(a)}<p>${description(a)}</p><a class="text-link" href="${url(a.slug)}">${t('Pogledaj apartman','Explore apartment','Apartment ansehen')} <span>↗</span></a></div></article>`).join('')}</div>`}
function map(){return S.mapEmbed?`<iframe title="${t('Lokacija objekta','Property location','Lage der Unterkunft')}" src="${esc(S.mapEmbed)}" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe>`:`<div class="map-placeholder"><div class="map-center">${icon('pin')}<h3 style="font-size:23px">${t('Tu počinje odmor','Your holiday starts here','Hier beginnt der Urlaub')}</h3><p>${t('Točnu lokaciju i kartu dodat ćemo nakon potvrde adrese.','The exact location and map will be added once the address is confirmed.','Die genaue Lage und Karte folgen nach Bestätigung der Adresse.')}</p></div></div>`}
function locationSection(){return `<section class="section cream"><div class="wrap location-grid"><div><span class="eyebrow">${t('PRONAĐITE NAS','FIND US','FINDEN SIE UNS')}</span><h2>${t('Korak bliže<br>vašem odmoru.','One step closer<br>to your holiday.','Ein Schritt näher<br>an Ihrem Urlaub.')}</h2><p>${S.location?esc(S.location):t('Ovdje ćemo podijeliti našu lokaciju, preporuke za dolazak automobilom i informacije o najbližoj zračnoj luci ili trajektnoj luci.','Here we will share our location, driving directions and information about the nearest airport or ferry port.','Hier finden Sie bald unseren Standort, die Anreise mit dem Auto sowie Informationen zum nächsten Flughafen oder Fährhafen.')}</p>${S.mapsUrl?`<a class="text-link" href="${esc(S.mapsUrl)}" target="_blank" rel="noopener">Google Maps ↗</a>`:`<a class="text-link" href="/kontakt/">${t('Javite nam se','Get in touch','Kontakt aufnehmen')} ↗</a>`}</div>${map()}</div></section>`}
function home(){return `<section class="hero">${photo('hero','',true)}<div class="wrap hero-content"><span class="eyebrow">${t('MALI BIJEG. VELIKE USPOMENE.','A LITTLE ESCAPE. LASTING MEMORIES.','KLEINE AUSZEIT. GROSSE ERINNERUNGEN.')}</span><h1>${t('Odmor.<br>U vašem <em>ritmu.</em>','A holiday.<br>At your <em>pace.</em>','Urlaub.<br>In Ihrem <em>Rhythmus.</em>')}</h1><p>${t('Jutra bez žurbe. Dani ispunjeni suncem.<br>Pronađite svoj kutak za odmor u apartmanima Meleh.','Unhurried mornings. Sun-filled days.<br>Find your place to unwind at Meleh Apartments.','Morgen ohne Eile. Tage voller Sonne.<br>Finden Sie Ihren Rückzugsort in den Meleh Apartments.')}</p><a class="btn light" href="/apartmani/">${t('Istražite apartmane','Explore apartments','Apartments entdecken')} <span>↗</span></a></div><div class="hero-bottom"><span>${t('CRIKVENICA · HRVATSKA','CRIKVENICA · CROATIA','CRIKVENICA · KROATIEN')}</span><span>${t('ISTRAŽITE','EXPLORE','ENTDECKEN')} <span>↓</span></span></div></section><section class="availability"><div class="wrap"><form id="availability"><div><label for="quick-in">${t('DATUM DOLASKA','CHECK-IN','ANREISE')}</label><input id="quick-in" name="arrival" type="date" required></div><div><label for="quick-out">${t('DATUM ODLASKA','CHECK-OUT','ABREISE')}</label><input id="quick-out" name="departure" type="date" required></div><div><label for="quick-guests">${t('BROJ OSOBA','GUESTS','PERSONEN')}</label><select name="adults" id="quick-guests">${[1,2,3,4,5].map(n=>`<option ${n===2?'selected':''} value="${n}">${n} ${t(n===1?'osoba':n<5?'osobe':'osoba',n===1?'guest':'guests',n===1?'Person':'Personen')}</option>`).join('')}</select></div><button class="btn" type="submit">${t('Upit za dostupnost','Enquire about availability','Verfügbarkeit anfragen')} <span>↗</span></button></form></div></section><section class="section"><div class="wrap"><div class="intro"><div class="intro-photo">${photo('beach')}<div class="photo-label">${t('Manje žurbe.<br>Više uživanja.','Slow down.<br>Settle in.','Weniger Eile.<br>Mehr genießen.')}</div></div><div class="intro-copy"><span class="eyebrow">${t('DOBRO DOŠLI U MELEH','WELCOME TO MELEH','WILLKOMMEN BEI MELEH')}</span><h2>${t('Mjesto u kojem<br>vrijeme usporava.','A place where<br>time slows down.','Ein Ort, an dem<br>die Zeit langsamer wird.')}</h2><p>${t('Najljepši odmor čine jednostavne stvari: prva jutarnja kava, dobra knjiga i vrijeme s ljudima koje volite. Ovu smo stranicu zamislili kao vaš prvi korak prema takvom odmoru.','The best holidays are made of simple things: the first coffee of the day, a good book and time with the people you love. Let this be your first step towards that kind of stay.','Die schönsten Urlaubstage bestehen aus einfachen Dingen: dem ersten Kaffee, einem guten Buch und Zeit mit Ihren Liebsten. Hier beginnt die Vorfreude darauf.')}</p><a class="text-link" href="/o-nama/">${t('Upoznajte našu priču','Discover our story','Unsere Geschichte entdecken')} ↗</a><p class="small-note">${t('Priču domaćina i stvarne sadržaje kuće dodat ćemo uskoro.','Our hosts’ story and confirmed property facilities will follow.','Die Geschichte der Gastgeber und bestätigte Ausstattung folgen.')}</p></div></div><div class="distances">${[['sea','beach',t('Plaža i more','Beach & sea','Strand & Meer')],['pin','center',t('Centar mjesta','Town centre','Ortszentrum')],['shop','shop',t('Trgovina','Grocery shop','Lebensmittel')],['food','restaurant',t('Restoran','Restaurant','Restaurant')],['plane','airport',t('Zračna luka','Airport','Flughafen')]].map(([i,k,l])=>`<div class="distance">${icon(i)}<strong>${l}</strong><small>${S.distances[k]||pending()}</small></div>`).join('')}</div></div></section><section class="section cream"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">${t('PROSTOR ZA VAŠ ODMOR','ROOM TO UNWIND','RAUM FÜR IHREN URLAUB')}</span><h2>${t('Pronađite svoj apartman.','Find your apartment.','Finden Sie Ihr Apartment.')}</h2></div><p>${t('Za jutra udvoje ili druženja s najdražima.<br>Odaberite prostor koji prati vaš ritam.','For mornings together or time with the family.<br>Choose a space that feels like you.','Für Zeit zu zweit oder mit der Familie.<br>Wählen Sie Ihren Lieblingsplatz.')}</p></div>${cards()}<p class="section-note">${t('Prikazani nazivi, kapaciteti, površine i fotografije služe kao ogledni primjer.','Names, capacities, sizes and photographs shown are illustrative.','Namen, Kapazitäten, Größen und Fotos dienen als Beispiele.')}</p></div></section><section class="section"><div class="wrap benefits"><div><span class="eyebrow">${t('JEDNOSTAVNO. OSOBNO. OPUŠTENO.','SIMPLE. PERSONAL. RELAXED.','EINFACH. PERSÖNLICH. ENTSPANNT.')}</span><h2>${t('Mali detalji.<br>Lijep osjećaj odmora.','Little details.<br>A lovely feeling.','Kleine Details.<br>Ein schönes Urlaubsgefühl.')}</h2></div><div class="benefit-grid">${[['chat',t('Direktan dogovor','A direct conversation','Direkter Kontakt'),t('Pošaljite svoje želje i pitanja u jednom upitu.','Share your wishes and questions in one enquiry.','Teilen Sie Ihre Wünsche und Fragen in einer Anfrage.')],['key',t('Prostor po vašoj mjeri','A space that suits you','Raum nach Ihren Wünschen'),t('Usporedite ogledne apartmane i pronađite svoj favorit.','Compare the sample apartments and find your favourite.','Vergleichen Sie die Beispielapartments.')],['heart',t('Vrijeme za vaše ljude','Time for your people','Zeit für Ihre Liebsten'),t('Za zajedničke trenutke koji postaju najljepše uspomene.','For shared moments that turn into favourite memories.','Für gemeinsame Momente und schöne Erinnerungen.')],['leaf',t('Inspirirano Mediteranom','Mediterranean inspiration','Mediterrane Inspiration'),t('Prirodni tonovi i opušten duh odmora.','Natural tones and an easy holiday spirit.','Natürliche Farben und entspannte Urlaubsstimmung.')]].map(([i,h,p])=>`<div class="benefit-item">${icon(i)}<h3>${h}</h3><p>${p}</p></div>`).join('')}</div></div></section><section class="wide-photo">${photo('sunset')}<div><span class="eyebrow">${t('UHVATITE TRENUTAK','SAVOUR THE MOMENT','DEN MOMENT GENIESSEN')}</span><h2>${t('Nigdje ne morate biti.<br>Osim ovdje.','Nowhere you need to be.<br>Except here.','Nirgendwo sein müssen.<br>Außer hier.')}</h2><p>${t('Večer na plaži Crni Molo u Crikvenici.','An evening at Crni Molo beach in Crikvenica.','Ein Abend am Strand Crni Molo in Crikvenica.')}</p></div></section><section class="section"><div class="wrap reviews">${icon('quote')}<span class="eyebrow">${t('RIJEČ GOSTIJU','GUEST STORIES','GÄSTESTIMMEN')}</span><h2>${t('Najljepše priče pišu gosti.','The best stories come from guests.','Die schönsten Geschichten schreiben Gäste.')}</h2><p>${t('Ovdje će biti objavljene provjerene recenzije naših gostiju, uz njihov izvor i ocjenu.','Verified guest reviews, their sources and ratings will appear here.','Hier erscheinen bestätigte Gästebewertungen mit Quelle und Bewertung.')}</p><span class="empty-tag">${t('Recenzije uskoro','Guest reviews coming soon','Gästebewertungen folgen')}</span></div></section>${locationSection()}`}
function pageHead(title,sub='',parent=''){return `<section class="page-head"><div class="wrap"><div class="breadcrumbs"><a href="/">${label('home')}</a> / ${parent?`<a href="/apartmani/">${label('apartments')}</a> / `:''}${title}</div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div></section>`}
function apartments(){return `${pageHead(label('apartments'),t('Tri ogledna prostora. Jedan osjećaj odmora. Istražite raspored, fotografije i opremu te odaberite svoj favorit.','Three sample spaces. One holiday feeling. Explore layouts, photos and facilities to find your favourite.','Drei Beispielapartments. Ein Urlaubsgefühl. Entdecken Sie Grundrisse, Fotos und Ausstattung.'))}<section class="section"><div class="wrap">${cards()}<p class="section-note">${t('Svi podaci i fotografije su ogledni i čekaju potvrdu vlasnika.','All details and photos are illustrative and await owner confirmation.','Alle Angaben und Fotos sind Beispiele und werden vom Eigentümer bestätigt.')}</p></div></section>`}
function detail(a){return `${pageHead(t('Apartman ','Apartment ','Apartment ')+a.name, t('Ogledni prikaz apartmana — raspored, kapacitet i opremu potvrdit ćemo prije primanja rezervacija.','Sample apartment — layout, capacity and equipment will be confirmed before accepting reservations.','Beispielapartment — Grundriss, Kapazität und Ausstattung werden vor Buchungen bestätigt.'),'apartments')}<section class="section" style="padding-top:35px"><div class="wrap">${specs(a)}<div class="detail-gallery"><button data-photo="${a.image}">${photo(a.image,'',true)}<span>${t('Uvećaj fotografiju','Enlarge photo','Foto vergrößern')} ⤢</span></button><button data-photo="detail">${photo('detail')}<span>${t('Pogledaj fotografije','View photographs','Fotos ansehen')} ↗</span></button></div><div class="detail-layout"><div class="detail-copy"><section><span class="eyebrow">${t('VAŠ PROSTOR ZA ODMOR','YOUR PLACE TO UNWIND','IHR ORT ZUM ENTSPANNEN')}</span><h2>${a.type==='family'?t('Zajedno je najljepše.','Better together.','Zusammen ist es am schönsten.'):t('Usporite. Ovdje ste.','Slow down. You’re here.','Entspannen Sie. Sie sind hier.')}</h2><p>${description(a)}</p><p>${t(`Ovaj primjer prikazuje apartman površine ${a.area} m² s ${a.rooms===1?'jednom spavaćom sobom':'dvije spavaće sobe'}, dnevnim boravkom, kuhinjom i kupaonicom. Podatak o katu (${a.floor}. kat) i sve sadržaje potrebno je potvrditi.`, `This example shows a ${a.area} m² apartment with ${a.rooms} bedroom(s), a living area, a kitchen and a bathroom. The floor (${a.floor}) and all facilities await confirmation.`, `Dieses Beispiel zeigt ein ${a.area} m² großes Apartment mit ${a.rooms} Schlafzimmer(n), Wohnbereich, Küche und Bad. Etage (${a.floor}) und Ausstattung werden noch bestätigt.`)}</p></section><section><h2>${t('Sve za ugodan boravak.','Everything for a lovely stay.','Alles für einen schönen Aufenthalt.')}</h2><p class="section-note">${t('Primjer mogućeg popisa opreme. Dostupnost pojedinih sadržaja još nije potvrđena.','Example equipment list. Availability of individual facilities is not yet confirmed.','Beispiel einer Ausstattungsliste. Die Verfügbarkeit ist noch nicht bestätigt.')}</p><div class="amenities">${[[t('Kuhinja i blagovaonica','Kitchen & dining','Küche & Essbereich'),t('Hladnjak · ploča za kuhanje · pećnica · aparat za kavu · kuhalo · posuđe','Fridge · hob · oven · coffee maker · kettle · cookware','Kühlschrank · Kochfeld · Backofen · Kaffeemaschine · Wasserkocher · Geschirr')],[t('Boravak i zabava','Living & entertainment','Wohnen & Unterhaltung'),t('Wi-Fi · TV · klimatizacija · prostor za sjedenje','Wi-Fi · TV · air conditioning · seating area','WLAN · TV · Klimaanlage · Sitzbereich')],[t('Spavanje i kupaonica','Bedroom & bathroom','Schlafzimmer & Bad'),t('Posteljina · ručnici · sušilo za kosu · prostor za odlaganje','Bed linen · towels · hair dryer · storage','Bettwäsche · Handtücher · Haartrockner · Stauraum')],[t('Vanjski prostor','Outdoor space','Außenbereich'),t('Balkon ili terasa · vrtni namještaj · parking — potrebno potvrditi','Balcony or terrace · outdoor furniture · parking — to be confirmed','Balkon oder Terrasse · Gartenmöbel · Parkplatz — zu bestätigen')]].map(([h,p])=>`<div class="amenity"><h3>${h}</h3><p>${p}</p></div>`).join('')}</div></section><section><h2>${t('Dobro je znati.','Good to know.','Gut zu wissen.')}</h2><div class="rule-list">${[[t('Prijava','Check-in','Anreise'),S.checkIn],[t('Odjava','Check-out','Abreise'),S.checkOut],[t('Kućni ljubimci','Pets','Haustiere'),S.pets],[t('Pušenje','Smoking','Rauchen'),S.smoking],[t('Mir u kući','Quiet hours','Ruhezeiten'),S.quietHours]].map(([k,v])=>`<div><strong>${k}</strong><span>${v||pending()}</span></div>`).join('')}</div></section></div><aside class="booking-box"><span class="eyebrow">${t('PLANIRAJTE BORAVAK','PLAN YOUR STAY','PLANEN SIE IHREN AUFENTHALT')}</span><h3>${t('Vaši datumi.<br>Vaš odmor.','Your dates.<br>Your holiday.','Ihre Reisedaten.<br>Ihr Urlaub.')}</h3><p>${t('Cjenik po sezonama bit će dodan nakon potvrde. Za svoj termin pripremite upit s datumima i brojem gostiju.','Seasonal prices will be added once confirmed. Prepare an enquiry with your dates and guest numbers.','Saisonpreise folgen nach Bestätigung. Bereiten Sie eine Anfrage mit Reisedaten und Gästezahl vor.')}</p><a class="btn" href="/kontakt/?apartman=${a.slug}">${cta()} ↗</a><p class="section-note">${t('Dostupnost se potvrđuje osobnim dogovorom. Slanje upita nije rezervacija.','Availability is confirmed personally. An enquiry is not a reservation.','Die Verfügbarkeit wird persönlich bestätigt. Eine Anfrage ist keine Buchung.')}</p></aside></div></div></section>`}
function about(){return `${pageHead(label('about'),t('Dobar odmor počinje osjećajem dobrodošlice.','A good holiday starts with feeling welcome.','Ein schöner Urlaub beginnt mit einem herzlichen Willkommen.'))}<section class="section"><div class="wrap"><div class="intro"><div class="intro-photo">${photo('beach')}<div class="photo-label">${t('S pažnjom<br>prema detaljima.','A little care.<br>In every detail.','Mit Liebe<br>zum Detail.')}</div></div><div class="intro-copy"><span class="eyebrow">${t('NAŠA PRIČA','OUR STORY','UNSERE GESCHICHTE')}</span><h2>${t('Odmor kojem se<br>želite vratiti.','A stay you’ll want<br>to return to.','Ein Urlaub, zu dem<br>Sie zurückkehren möchten.')}</h2><p>${t('Meleh zamišljamo kao mjesto jednostavnih užitaka: toplog dočeka, opuštenih jutara i vremena koje pripada samo vama. Želimo da se već pri prvom kontaktu osjećate dobrodošlo.','We imagine Meleh as a place for simple pleasures: a warm welcome, relaxed mornings and time that belongs to you. We want you to feel welcome from the first conversation.','Wir stellen uns Meleh als Ort einfacher Freuden vor: ein herzlicher Empfang, entspannte Morgen und Zeit für Sie. Schon beim ersten Kontakt sollen Sie sich willkommen fühlen.')}</p><p>${t('Osobnu priču domaćina, tradiciju kuće i preporuke iz prve ruke dodat ćemo kad vlasnici podijele svoje podatke.','The hosts’ personal story, the history of the house and local recommendations will be added when provided by the owners.','Die persönliche Geschichte der Gastgeber, die Tradition des Hauses und lokale Tipps folgen mit den Angaben der Eigentümer.')}</p><span class="signature">Meleh Apartmani</span></div></div><div class="about-values">${[[t('Osobno','Personal','Persönlich'),t('Prostor za vaša pitanja, želje i detalje koji su vam važni.','Room for your questions, wishes and the details that matter to you.','Platz für Ihre Fragen, Wünsche und wichtige Details.')],[t('Jednostavno','Simple','Einfach'),t('Jasne informacije i direktan kontakt za dogovor o boravku.','Clear information and direct contact to arrange your stay.','Klare Informationen und direkter Kontakt für Ihren Aufenthalt.')],[t('Opušteno','Relaxed','Entspannt'),t('Inspiracija za dane u kojima ne morate gledati na sat.','Inspiration for days when there’s no need to watch the clock.','Inspiration für Tage, an denen die Uhr keine Rolle spielt.')]].map(([h,p])=>`<div><h3>${h}</h3><p>${p}</p></div>`).join('')}</div></div></section>`}
const categories=()=>[['all',t('Sve fotografije','All photos','Alle Fotos')],['house',t('Kuća i okućnica','House & garden','Haus & Garten')],['location',t('Lokacija i plaža','Location & beach','Lage & Strand')],...S.apartments.map(a=>[a.slug,a.name])];
function gallery(){return `${pageHead(label('gallery'),t('Stvarni prizori Crikvenice, njezinih plaža i mora. Fotografije interijera su ogledne i zamijenit ćemo ih fotografijama objekta.','Real views of Crikvenica, its beaches and the sea. Interior photographs are samples and will be replaced with actual property photos.','Echte Ansichten von Crikvenica, seinen Stränden und dem Meer. Die Beispielinterieurs werden durch echte Fotos der Unterkunft ersetzt.'))}<section class="section" style="padding-top:40px"><div class="wrap"><div class="filter-row" role="group" aria-label="${t('Kategorije fotografija','Photo categories','Fotokategorien')}">${categories().map(([k,l],i)=>`<button class="filter ${i===0?'active':''}" data-category="${k}" aria-pressed="${i===0}">${l}</button>`).join('')}</div><div class="gallery-grid">${galleryItems('all')}</div></div></section>`}
function galleryItems(cat){return S.photos.filter(p=>cat==='all'||p.category===cat).map(p=>`<button class="gallery-item" data-photo="${p.key}">${photo(p.key)}<span>${categories().find(c=>c[0]===p.category)?.[1]||'Meleh'} ⤢</span></button>`).join('')}
function contact(){return `${pageHead(label('contact'),t('Recite nam kako zamišljate svoj odmor. Pripremite upit, a kontakt domaćina dodat ćemo naknadno.','Tell us about your holiday plans. Prepare your enquiry; host contact details will be added later.','Erzählen Sie uns von Ihren Urlaubsplänen. Bereiten Sie Ihre Anfrage vor; Kontaktdaten folgen.'))}<section class="section"><div class="wrap contact-grid"><div><form id="inquiry" class="form-grid"><label class="field">${t('Ime i prezime','Full name','Vor- und Nachname')} *<input name="name" required autocomplete="name" maxlength="120" placeholder="${t('Vaše ime i prezime','Your full name','Ihr vollständiger Name')}"></label><label class="field">${t('E-mail adresa','Email address','E-Mail-Adresse')} *<input name="email" required type="email" autocomplete="email" maxlength="200" placeholder="ime@primjer.hr"></label><label class="field">${t('Telefon / WhatsApp','Phone / WhatsApp','Telefon / WhatsApp')}<input name="phone" type="tel" autocomplete="tel" maxlength="50" placeholder="+385 …"></label><label class="field">${t('Željeni apartman','Preferred apartment','Gewünschtes Apartment')}<select name="apartment"><option value="">${t('Nisam siguran / Svejedno','Not sure / Any apartment','Noch unsicher / Egal')}</option>${S.apartments.map(a=>`<option value="${a.slug}">${a.name}</option>`).join('')}</select></label><label class="field">${t('Datum dolaska','Check-in date','Anreisedatum')} *<input name="arrival" type="date" required></label><label class="field">${t('Datum odlaska','Check-out date','Abreisedatum')} *<input name="departure" type="date" required></label><label class="field">${t('Odrasli','Adults','Erwachsene')} *<input name="adults" type="number" min="1" max="20" value="2" required></label><label class="field">${t('Djeca','Children','Kinder')}<input name="children" type="number" min="0" max="20" value="0"></label><label class="field full">${t('Vaša poruka','Your message','Ihre Nachricht')}<textarea name="message" maxlength="5000" placeholder="${t('Vaše želje, pitanja ili nešto što bismo trebali znati…','Your wishes, questions or anything we should know…','Ihre Wünsche, Fragen oder weitere Informationen…')}"></textarea></label><label class="consent full"><input type="checkbox" required name="consent"><span>${t('Pročitao/la sam','I have read the','Ich habe die')} <a href="/privatnost/" style="text-decoration:underline">${t('pravila privatnosti','privacy notice','Datenschutzhinweise')}</a>. ${t('Razumijem da se upit u oglednoj verziji priprema lokalno i ne šalje automatski.','I understand that this demo prepares my enquiry locally and does not send it automatically.','Ich verstehe, dass die Demo meine Anfrage lokal vorbereitet und nicht automatisch versendet.')}</span></label><div class="full"><button class="btn" type="submit">${S.email?cta():t('Pripremi upit','Prepare enquiry','Anfrage vorbereiten')} ↗</button><p class="section-note">${t('Bez obveze rezervacije. Osobni podaci ne spremaju se na poslužitelj.','No reservation commitment. Personal details are not stored on a server.','Keine verbindliche Buchung. Persönliche Angaben werden nicht auf einem Server gespeichert.')}</p><p class="form-error" id="form-error" role="alert"></p></div></form><div id="inquiry-result" aria-live="polite"></div></div><aside class="contact-aside"><h3>${t('Radujemo se vašoj poruci.','We look forward to your message.','Wir freuen uns auf Ihre Nachricht.')}</h3><div class="contact-detail"><strong>${t('Adresa','Address','Adresse')}</strong><p>${esc(S.address)||pending()}</p></div><div class="contact-detail"><strong>E-mail</strong><p>${S.email?`<a href="mailto:${esc(S.email)}">${esc(S.email)}</a>`:pending()}</p></div><div class="contact-detail"><strong>${t('Telefon','Phone','Telefon')}</strong><p>${S.phone?`<a href="tel:${esc(S.phone)}">${esc(S.phone)}</a>`:pending()}</p></div>${S.whatsapp?`<a class="btn outline" href="https://wa.me/${S.whatsapp.replace(/\D/g,'')}" target="_blank" rel="noopener">WhatsApp ↗</a>`:''}${S.viber?`<a class="btn outline" href="viber://chat?number=${encodeURIComponent(S.viber)}">Viber ↗</a>`:''}<p class="small-note">${t('Telefonske i WhatsApp/Viber poveznice aktivirat ćemo nakon unosa stvarnog broja.','Phone and WhatsApp/Viber links will be activated once the real number is provided.','Telefon- und WhatsApp/Viber-Links werden nach Eingabe der echten Nummer aktiviert.')}</p></aside></div></section>${locationSection()}`}
function legal(kind){const privacy=kind==='privacy';return `${pageHead(privacy?t('Pravila privatnosti','Privacy notice','Datenschutzhinweise'):t('Uvjeti korištenja','Terms of use','Nutzungsbedingungen'))}<section class="section"><div class="wrap legal"><span class="empty-tag">${t('Obavijest za oglednu verziju','Demo version notice','Hinweis zur Demo-Version')}</span>${privacy?`<h2>${t('Vaši podaci u ovoj verziji','Your data in this version','Ihre Daten in dieser Version')}</h2><p>${t('Obrazac obrađuje unesene podatke samo u vašem pregledniku radi pripreme teksta upita. Ova stranica ne šalje obrazac domaćinu i ne sprema njegove podatke na poslužitelj. Kopirani tekst ili preuzetu datoteku šaljete sami odabranom primatelju.','The form processes your entries in your browser to prepare an enquiry. It does not send the form to a host or store form details on a server. You choose whether to send copied text or a downloaded file to a recipient.','Das Formular verarbeitet Ihre Angaben im Browser, um eine Anfrage vorzubereiten. Es sendet sie nicht an Gastgeber und speichert Formulardaten nicht auf einem Server. Kopierten Text oder eine heruntergeladene Datei versenden Sie selbst.')}</p><h2>${t('Postavke i vanjski sadržaj','Preferences and external content','Einstellungen und externe Inhalte')}</h2><p>${t('U lokalnu pohranu preglednika spremamo samo odabrani jezik i temu. Ne koristimo analitičke alate ni marketinške kolačiće. Fontovi se učitavaju preko Google Fonts usluge, pri čemu Google prima tehničke podatke veze poput IP adrese. Hosting također obrađuje tehničke podatke potrebne za dostavu stranice.','Only your language and theme preferences are saved in browser local storage. We use no analytics or marketing cookies. Fonts are loaded via Google Fonts, which receives technical connection data such as your IP address. Hosting also processes technical data needed to deliver the site.','Im lokalen Browserspeicher speichern wir nur Ihre Sprach- und Themenwahl. Wir verwenden keine Analyse- oder Marketing-Cookies. Schriftarten werden über Google Fonts geladen; Google erhält dabei technische Verbindungsdaten wie die IP-Adresse. Das Hosting verarbeitet ebenfalls zur Bereitstellung notwendige technische Daten.')}</p><h2>${t('Prije stvarnog primanja upita','Before accepting real enquiries','Vor echten Anfragen')}</h2><p>${t('Vlasnik treba unijeti identitet i kontakt voditelja obrade, svrhe i pravnu osnovu obrade, rokove čuvanja, primatelje podataka te postupak za ostvarivanje prava korisnika. Ova obavijest opisuje samo postojeću oglednu funkcionalnost.','The owner must provide the data controller’s identity and contact details, purposes and legal basis, retention periods, recipients and the process for exercising user rights. This notice describes only the current demo functionality.','Der Eigentümer muss Verantwortliche, Kontaktdaten, Zwecke, Rechtsgrundlage, Aufbewahrungsfristen, Empfänger und Verfahren zur Ausübung der Nutzerrechte ergänzen. Dieser Hinweis beschreibt nur die aktuelle Demo.')}</p>`:`<h2>${t('Ogledni sadržaj','Illustrative content','Beispielinhalte')}</h2><p>${t('Nazivi apartmana, fotografije, kapaciteti, površine i prikazani sadržaji služe kao dizajnerski primjer. Ne predstavljaju potvrđenu ponudu smještaja. Stvarne podatke, cijene i dostupnost dodat će vlasnik.','Apartment names, photos, capacities, floor areas and amenities are design examples, not a confirmed accommodation offer. Actual details, prices and availability will be provided by the owner.','Apartmentnamen, Fotos, Kapazitäten, Flächen und Ausstattung sind Designbeispiele und kein bestätigtes Unterkunftsangebot. Echte Angaben, Preise und Verfügbarkeit ergänzt der Eigentümer.')}</p><h2>${t('Upiti i rezervacije','Enquiries and reservations','Anfragen und Buchungen')}</h2><p>${t('Priprema upita ne znači slanje poruke niti potvrdu rezervacije. Rezervacija može biti potvrđena tek nakon izravnog dogovora s domaćinom. Uvjeti plaćanja, otkazivanja, kućnog reda i konačne cijene bit će navedeni nakon potvrde vlasnika.','Preparing an enquiry does not send a message or confirm a reservation. A booking can only be confirmed through direct agreement with the host. Payment, cancellation, house rules and final prices will be provided after owner confirmation.','Das Vorbereiten einer Anfrage versendet keine Nachricht und bestätigt keine Buchung. Eine Buchung erfolgt erst nach direkter Vereinbarung mit dem Gastgeber. Zahlungs-, Storno- und Hausregeln sowie Preise folgen nach Bestätigung.')}</p>`}</div></section>`}
let currentPhotos=[],photoIndex=0,lastPhotoTrigger=null;
function showPhoto(key){currentPhotos=Array.from(document.querySelectorAll('[data-photo]')).map(b=>image(b.dataset.photo));currentPhotos=currentPhotos.filter((p,i,a)=>a.findIndex(x=>x.key===p.key)===i);photoIndex=currentPhotos.findIndex(p=>p.key===key);lastPhotoTrigger=document.activeElement;updatePhoto();document.querySelector('#lightbox').showModal()}
function updatePhoto(){const p=currentPhotos[photoIndex];if(!p)return;const d=document.querySelector('#lightbox');d.querySelector('img').src='/assets/'+p.file;d.querySelector('img').alt=t(p.alt,p.altEn||'Illustrative apartment interior',p.altDe||'Beispielinterieur eines Apartments');d.querySelector('figcaption').textContent=`${photoIndex+1} / ${currentPhotos.length} · ${p.category==='location'?t('Crikvenica, Hrvatska','Crikvenica, Croatia','Crikvenica, Kroatien'):t('Ogledna fotografija interijera','Illustrative interior photograph','Beispielfoto eines Interieurs')}`;d.querySelector('.prev').disabled=currentPhotos.length<2;d.querySelector('.next').disabled=currentPhotos.length<2}
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function nextDay(v){const d=new Date(v+'T12:00:00');d.setDate(d.getDate()+1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function setupDates(form){const start=form.querySelector('[name=arrival]'),end=form.querySelector('[name=departure]');if(!start)return;start.min=today();end.min=today();function validate(){end.setCustomValidity('');end.min=start.value?nextDay(start.value):today();if(end.value&&start.value&&end.value<=start.value)end.setCustomValidity(t('Odlazak mora biti nakon dolaska.','Check-out must be after check-in.','Die Abreise muss nach der Anreise liegen.'))}start.addEventListener('change',validate);end.addEventListener('change',validate);validate()}
function render(){const path=decodeURIComponent(location.pathname).replace(/\/+$/,'')||'/';let body,title;const apartment=S.apartments.find(a=>path==='/apartmani/'+a.slug);if(path==='/'){body=home();title=t('Odmor u svom ritmu','A holiday at your pace','Urlaub in Ihrem Rhythmus')}else if(path==='/apartmani'){body=apartments();title=label('apartments')}else if(apartment){body=detail(apartment);title=apartment.name}else if(path==='/o-nama'){body=about();title=label('about')}else if(path==='/galerija'){body=gallery();title=label('gallery')}else if(path==='/kontakt'){body=contact();title=label('contact')}else if(path==='/fotografije'){body=photoCredits();title=t('Izvori fotografija','Photo credits','Bildnachweise')}else if(path==='/privatnost'||path==='/uvjeti'){body=legal(path==='/privatnost'?'privacy':'terms');title=t('Korisne informacije','Useful information','Nützliche Informationen')}else{title='404';body=pageHead(t('Stranica nije pronađena','Page not found','Seite nicht gefunden'))+`<section class="section wrap"><a class="btn" href="/">${label('home')} ↗</a></section>`}document.documentElement.lang=lang;document.title=`${title} · Meleh Apartmani`;document.querySelector('#app').innerHTML=header()+`<main id="main">${body}</main>`+footer();updateThemeToggle();document.querySelector('.theme-toggle').addEventListener('click',()=>window.MelehTheme.toggle());document.querySelector('.language').addEventListener('change',e=>{lang=e.target.value;localStorage.setItem('meleh-language',lang);render()});document.querySelector('.menu-button').addEventListener('click',e=>{const nav=document.querySelector('.nav-links'),open=nav.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open);e.currentTarget.textContent=open?'×':'☰'});document.querySelectorAll('nav a').forEach(a=>{if(a.pathname===location.pathname){a.classList.add('active');a.setAttribute('aria-current','page')}});document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.filter').forEach(f=>{f.classList.toggle('active',f===b);f.setAttribute('aria-pressed',f===b)});document.querySelector('.gallery-grid').innerHTML=galleryItems(b.dataset.category)}));const quick=document.querySelector('#availability');if(quick){setupDates(quick);quick.addEventListener('submit',e=>{e.preventDefault();navigate('/kontakt/?'+new URLSearchParams(new FormData(quick)).toString())})}const form=document.querySelector('#inquiry');if(form){const query=new URLSearchParams(location.search);for(const [key,val]of query){const field=form.elements[key==='apartman'?'apartment':key];if(field&&['apartment','arrival','departure','adults'].includes(field.name))field.value=val}setupDates(form);form.addEventListener('submit',submitInquiry)}}
function submitInquiry(e){e.preventDefault();const f=e.currentTarget;const error=document.querySelector('#form-error');error.textContent='';const data=Object.fromEntries(new FormData(f));if(!data.name.trim()){error.textContent=t('Unesite ime i prezime.','Please enter your full name.','Bitte geben Sie Ihren Namen ein.');f.elements.name.focus();return}if(data.arrival<today()||data.departure<=data.arrival){error.textContent=t('Provjerite datume dolaska i odlaska.','Please check your arrival and departure dates.','Bitte prüfen Sie Ihre Reisedaten.');return}const a=S.apartments.find(a=>a.slug===data.apartment);if(a&&Number(data.adults)+Number(data.children)>a.guests.split('+').reduce((n,v)=>n+Number(v.trim()),0)){error.textContent=t('Broj gostiju prelazi ogledni kapacitet apartmana. Odaberite drugi apartman ili opciju „Svejedno”.','Guest count exceeds this apartment’s sample capacity. Choose another apartment or “Any apartment”.','Die Gästezahl übersteigt die Beispielkapazität. Wählen Sie ein anderes Apartment oder „Egal”.');return}const text=[t('Upit za boravak — Meleh Apartmani','Stay enquiry — Meleh Apartments','Aufenthaltsanfrage — Meleh Apartments'),' ',`${t('Ime','Name','Name')}: ${data.name.trim()}`,`E-mail: ${data.email}`,`${t('Telefon','Phone','Telefon')}: ${data.phone||'—'}`,`${t('Apartman','Apartment','Apartment')}: ${a?.name||t('Svejedno','Any','Egal')}`,`${t('Dolazak','Check-in','Anreise')}: ${data.arrival}`,`${t('Odlazak','Check-out','Abreise')}: ${data.departure}`,`${t('Odrasli','Adults','Erwachsene')}: ${data.adults}`,`${t('Djeca','Children','Kinder')}: ${data.children||0}`,'',data.message||''].join('\n');const result=document.querySelector('#inquiry-result');result.innerHTML=`<div class="inquiry-result"><h3>${t('Vaš upit je pripremljen.','Your enquiry is ready.','Ihre Anfrage ist vorbereitet.')}</h3><p class="section-note">${S.email?t('Otvorite ga u svojoj aplikaciji za e-poštu i pošaljite domaćinu.','Open it in your email app and send it to the host.','Öffnen Sie die Anfrage in Ihrer E-Mail-App und senden Sie sie an den Gastgeber.'):t('Upit nije poslan. Kontakt domaćina još nije unesen. Tekst možete kopirati ili preuzeti.','Your enquiry has not been sent. Host contact details have not been added yet. You can copy or download the text.','Die Anfrage wurde nicht versendet. Die Kontaktdaten fehlen noch. Sie können den Text kopieren oder herunterladen.')}</p><pre>${esc(text)}</pre><div class="actions">${S.email?`<a class="btn" href="mailto:${esc(S.email)}?subject=${encodeURIComponent('Meleh — '+data.arrival)}&body=${encodeURIComponent(text)}">${t('Otvori e-poštu','Open email app','E-Mail öffnen')} ↗</a>`:''}<button class="btn" id="copy-inquiry">${t('Kopiraj upit','Copy enquiry','Anfrage kopieren')}</button><button class="btn outline" id="download-inquiry">${t('Preuzmi tekst','Download text','Text herunterladen')}</button></div><p id="copy-status" role="status" class="section-note"></p></div>`;document.querySelector('#copy-inquiry').onclick=async()=>{try{await navigator.clipboard.writeText(text);document.querySelector('#copy-status').textContent=t('Upit je kopiran.','Enquiry copied.','Anfrage kopiert.')}catch{document.querySelector('#copy-status').textContent=t('Kopiranje nije dostupno. Preuzmite tekst upita.','Copying unavailable. Download the enquiry text.','Kopieren nicht verfügbar. Laden Sie den Text herunter.')}};document.querySelector('#download-inquiry').onclick=()=>{const u=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='Meleh-upit.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};result.scrollIntoView({behavior:'smooth',block:'center'})}
function navigate(href){history.pushState({},'',href);render();window.scrollTo(0,0)}
document.addEventListener('click',e=>{const p=e.target.closest('[data-photo]');if(p){showPhoto(p.dataset.photo);return}const a=e.target.closest('a');if(!a||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||a.target||a.download||a.origin!==location.origin||!a.pathname.startsWith('/')||a.hash)return;if(a.protocol==='http:'||a.protocol==='https:'){e.preventDefault();navigate(a.pathname+a.search)}});
window.addEventListener('meleh-theme-change',updateThemeToggle);
const lightbox=document.querySelector('#lightbox');lightbox.querySelector('.close-light').onclick=()=>lightbox.close();lightbox.addEventListener('close',()=>lastPhotoTrigger?.focus());lightbox.querySelector('.prev').onclick=()=>{photoIndex=(photoIndex-1+currentPhotos.length)%currentPhotos.length;updatePhoto()};lightbox.querySelector('.next').onclick=()=>{photoIndex=(photoIndex+1)%currentPhotos.length;updatePhoto()};lightbox.addEventListener('keydown',e=>{if(e.key==='ArrowRight')lightbox.querySelector('.next').click();if(e.key==='ArrowLeft')lightbox.querySelector('.prev').click()});lightbox.addEventListener('click',e=>{if(e.target===lightbox)lightbox.close()});window.addEventListener('popstate',()=>{render();window.scrollTo(0,0)});render();

function updateThemeToggle(){
  const button=document.querySelector('.theme-toggle');if(!button)return;
  const dark=document.documentElement.dataset.theme==='dark';
  const action=dark?t('Prebaci na svijetlu temu','Switch to light theme','Zum hellen Design wechseln'):t('Prebaci na tamnu temu','Switch to dark theme','Zum dunklen Design wechseln');
  button.setAttribute('aria-label',action);button.setAttribute('title',action);button.setAttribute('aria-pressed',String(dark));
  button.innerHTML=dark?icon('sun'):'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M20.4 14.5A8.7 8.7 0 0 1 9.5 3.6a8.7 8.7 0 1 0 10.9 10.9Z"/></svg>';
}
function photoCredits(){return `${pageHead(t('Izvori fotografija','Photo credits','Bildnachweise'),t('Crikvenica kroz objektiv lokalnih prizora.','Crikvenica through photographs of the coast.','Crikvenica in Bildern der Küste.'))}<section class="section"><div class="wrap legal"><p>${t('Prizori destinacije prikazuju Crikvenicu. Fotografije interijera su ogledne i ne prikazuju apartmane Meleh.','Destination photographs show Crikvenica. Interior photographs are illustrative and do not show Meleh apartments.','Die Ortsfotos zeigen Crikvenica. Die Beispielinterieurs zeigen keine Meleh Apartments.')}</p>${S.photoCredits.map(c=>`<article class="photo-credit"><h2>${esc(c.title)}</h2><p>${esc(c.author)} · <a href="${esc(c.source)}" target="_blank" rel="noopener">Wikimedia Commons ↗</a> · <a href="${esc(c.licenseUrl)}" target="_blank" rel="license noopener">${esc(c.license)}</a></p><p>${t('Fotografija je prilagođena veličini prikaza; pojedini prikazi koriste izrez i zatamnjenje preko CSS-a. Prilagođeni prikaz fotografije dostupan je pod istom licencom.','The photograph is resized for display; some views use CSS cropping and a dark overlay. Adapted photo displays are available under the same license.','Das Foto wurde für die Anzeige skaliert; einige Ansichten nutzen CSS-Ausschnitt und Abdunklung. Bearbeitete Fotodarstellungen stehen unter derselben Lizenz.')}</p><a class="text-link" href="/assets/${esc(c.file)}" target="_blank">${t('Otvori fotografiju','Open photograph','Foto öffnen')} ↗</a></article>`).join('')}<h2>${t('Ogledni interijeri','Illustrative interiors','Beispielinterieurs')}</h2><p>Unsplash · ${t('Privremeni primjeri rasporeda i atmosfere smještaja.','Temporary examples of accommodation layouts and atmosphere.','Vorläufige Beispiele für Grundrisse und Wohnatmosphäre.')}</p><p>${[['room.jpg','photo-1600210492486-724fe5c67fb0'],['bedroom.jpg','photo-1611892440504-42a792e24d32'],['house.jpg','photo-1600607687920-4e2a09cf159d'],['detail.jpg','photo-1600210491892-03d54c0aaf87']].map(([name,id])=>`<a href="https://images.unsplash.com/${id}" target="_blank" rel="noopener">${name} ↗</a>`).join(' · ')}</p></div></section>`}
